6\u0435\u043d \u0434\u0440\u0430\u0444\u0442 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430: \u0433\u0440\u0443\u043f\u043f\u044b \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f, \u043c\u0435\u0442\u0440\u0438\u043a\u0438, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432 \u0438 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f", "answer": "### 1. \u041e\u0441\u043c\u043e\u0442\u0440 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0438 \u0432\u0432\u043e\u0434\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445\n- **\u041e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435:** \u0418\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0441\u0440\u0435\u0434\u0430 \u0431\u0435\u0437 \u043f\u0440\u0435\u0434\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a; \u0437\u0430\u0434\u0430\u0447\u0430 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f **design-only** (\u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0435 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442\u0441\u044f).\n- **\u0412\u0432\u043e\u0434\u043d\u044b\u0435:** \u0424\u0430\u0439\u043b `task.json` \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0443 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u0432\u043e\u043f\u0440\u043e\u0441\u0430 (\u0432\u043b\u0438\u044f\u043d\u0438\u0435 CoT \u043d\u0430 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c LLM-\u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u0432 WorkArena++) \u0438 \u0441\u0441\u044b\u043b\u043a\u0443 \u043d\u0430 \u0442\u043e\u043f\u0438\u043a \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 `neurips2024/97713/3:setup_1`.\n\n---\n\n### 2. \u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\n\n#### \u0410. \u0418\u0441\u0441\u043b\u0435\u0434\u0443\u0435\u043c\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 \u0438 \u0433\u0440\u0443\u043f\u043f\u044b \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (Independent Variables)\n\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u043c \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u043f\u0440\u0438 \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0438 \u0440\u0435\u0436\u0438\u043c\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439:\n1. **Direct Action (No-CoT / Baseline):** \u041c\u043e\u0434\u0435\u043b\u044c \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u0442\u0435\u043a\u0443\u0449\u0435\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435 (\u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b, \u0438\u0441\u0442\u043e\u0440\u0438\u044e) \u0438 \u0434\u043e\u043b\u0436\u043d\u0430 \u043d\u0435\u043f\u043e\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0432\u044b\u0434\u0430\u0442\u044c \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u043c\u043e\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 (action call) \u0431\u0435\u0437 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0445 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439.\n2. **ReAct / Step-by-Step CoT (\u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430):** \u041c\u043e\u0434\u0435\u043b\u044c \u043f\u0435\u0440\u0435\u0434 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0435\u0439 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u0441\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0431\u043b\u043e\u043a \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 (`Thought:`), \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0438\u0439 \u043e\u0446\u0435\u043d\u043a\u0443 \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441\u0430, \u0430\u043d\u0430\u043b\u0438\u0437 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f \u0438 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u0448\u0430\u0433\u0430, \u043f\u043e\u0441\u043b\u0435 \u0447\u0435\u0433\u043e \u0432\u044b\u0434\u0430\u0435\u0442 `Action:`.\n3. **\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430 Few-shot \u044d\u0444\u0444\u0435\u043a\u0442:**\n   - Zero-shot Direct vs. Zero-shot CoT\n   - Few-shot Direct vs. Few-shot CoT (\u0441 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u043c\u0438 \u043f\u0440\u0438\u043c\u0435\u0440\u0430\u043c\u0438 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0439, \u043e\u0447\u0438\u0449\u0435\u043d\u043d\u044b\u043c\u0438 \u043e\u0442 \u043f\u043e\u043b\u044f `Thought` \u0432 Direct-\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0435), \u0447\u0442\u043e\u0431\u044b \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0432\u043b\u0438\u044f\u043d\u0438\u0435 \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u0439 \u043a\u0430\u043a \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u0430.\n\n#### \u0411. \u041c\u043e\u0434\u0435\u043b\u0438 (LLM Backbones)\n\u0414\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0433\u0435\u043d\u0435\u0440\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u043e\u0441\u0442\u0438 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0431\u0435\u0440\u0435\u043c \u0441\u0440\u0435\u0437 \u043c\u043e\u0434\u0435\u043b\u0435\u0439:\n- \u0424\u043b\u0430\u0433\u043c\u0430\u043d\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u043f\u0440\u0438\u0435\u0442\u0430\u0440\u043d\u044b\u0435 SOTA (\u043d\u0430\u043f\u0440. GPT-4o, Claude 3.5 Sonnet);\n- \u041e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0432\u0435\u0441\u0430 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u0433\u043e \u043a\u043b\u0430\u0441\u0441\u0430 (\u043d\u0430\u043f\u0440. Llama-3.1-70B-Instruct, Qwen2.5-72B-Instruct / Qwen2-VL).\n\n#### \u0412. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438 (Dependent Variables)\n1. **\u0413\u043b\u0430\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430:** Success Rate (SR, %) \u2014 \u0434\u043e\u043b\u044f \u0443\u0441\u043f\u0435\u0448\u043d\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447 \u043f\u043e \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0432\u0430\u043b\u0438\u0434\u0430\u0442\u043e\u0440\u0430\u043c WorkArena++.\n2. **\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u0438 \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438:**\n   - \u0414\u043b\u0438\u043d\u0430 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438 (\u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432 \u0434\u043e \u0443\u0441\u043f\u0435\u0445\u0430/\u0442\u0430\u0439\u043c\u0430\u0443\u0442\u0430);\n   - \u0414\u043e\u043b\u044f \u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0447\u0435\u0441\u043a\u0438 \u0438 \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 (Invalid Action Rate / Grounding Errors);\n   - Subgoal completion rate (\u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u043f\u043e \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u043c \u044d\u0442\u0430\u043f\u0430\u043c \u0441\u043b\u043e\u0436\u043d\u044b\u0445 workflow);\n   - \u0417\u0430\u0442\u0440\u0430\u0442\u044b \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (Token overhead per successful task) \u0438 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0430 (latency).\n\n#### \u0413. \u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445\n- \u0418\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f (paired evaluation) \u043d\u0430 \u0432\u0441\u0435\u0445 \u0437\u0430\u0434\u0430\u0447\u0430\u0445 \u0441\u043f\u043b\u0438\u0442\u0430 WorkArena++.\n- \u0414\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f (\u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0430 $T=0$ \u0438\u043b\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 seed \u0434\u043b\u044f \u0432\u044b\u0431\u043e\u0440\u043a\u0438).\n- \u0415\u0434\u0438\u043d\u044b\u0439 \u043b\u0438\u043c\u0438\u0442 \u0448\u0430\u0433\u043e\u0432 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 ($N_{\\max}$) \u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0442\u0430\u0439\u043c-\u0430\u0443\u0442\u044b \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439.\n\n---\n\n### 3. \u041f\u0440\u0438\u043d\u0446\u0438\u043f\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u0441\u0435\u0440\u044b\u0435 \u0437\u043e\u043d\u044b\n\n**\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (Assumptions):**\n1. \u0412 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0435 WorkArena++ \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0443\u0441\u043f\u0435\u0448\u043d\u043e\u0441\u0442\u0438 \u0437\u0430\u0434\u0430\u0447\u0438 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0438 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0447\u0435\u0440\u0435\u0437 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 ServiceNow / BrowserGym.\n2. \u0418\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0430\u0433\u0435\u043d\u0442\u0430 \u0441 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043e\u043c \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0435\u043d (\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u043b\u0438\u0431\u043e AXTree/DOM, \u043b\u0438\u0431\u043e \u0441\u043a\u0440\u0438\u043d\u0448\u043e\u0442\u044b + \u0441\u043f\u0438\u0441\u043e\u043a \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439).\n\n**\u0421\u0435\u0440\u044b\u0435 \u0437\u043e\u043d\u044b \u0438 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u0434\u043b\u044f \u0443\u0442\u043e\u0447\u043d\u0435\u043d\u0438\u044f (Uncertainties):**\n1. *\u041c\u043e\u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0439:* \u041f\u0440\u0435\u0434\u043f\u043e\u043b\u04