u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0438 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\n\n### 1.1. \u041a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0437\u0430\u0434\u0430\u0447\u0438\n\u0411\u0435\u043d\u0447\u043c\u0430\u0440\u043a **WorkArena++** (ServiceNow / BrowserGym, NeurIPS 2024) \u043c\u043e\u0434\u0435\u043b\u0438\u0440\u0443\u0435\u0442 \u0441\u043b\u043e\u0436\u043d\u044b\u0435 \u043c\u043d\u043e\u0433\u043e\u0448\u0430\u0433\u043e\u0432\u044b\u0435 \u0440\u0430\u0431\u043e\u0447\u0438\u0435 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u044b \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u0432\u043d\u044f (\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0438\u043d\u0446\u0438\u0434\u0435\u043d\u0442\u0430\u043c\u0438, \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u044b\u0445 \u0444\u043e\u0440\u043c, \u043f\u043e\u0438\u0441\u043a \u0432 \u0431\u0430\u0437\u0430\u0445 \u0437\u043d\u0430\u043d\u0438\u0439, \u043c\u0430\u043d\u0438\u043f\u0443\u043b\u044f\u0446\u0438\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u043c\u0438 \u0438 \u0441\u043f\u0438\u0441\u043a\u0430\u043c\u0438). \u0412 \u043e\u0442\u043b\u0438\u0447\u0438\u0435 \u043e\u0442 \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0432\u0435\u0431-\u0431\u0440\u0430\u0443\u0437\u0438\u043d\u0433\u0430, \u0437\u0430\u0434\u0430\u0447\u0438 WorkArena++ \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0438\u0437\u0443\u044e\u0442\u0441\u044f:\n- \u0411\u043e\u043b\u044c\u0448\u0438\u043c \u043e\u0431\u044a\u0435\u043c\u043e\u043c \u0432\u0438\u0437\u0443\u0430\u043b\u044c\u043d\u043e-\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0439 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438 (\u0440\u0430\u0437\u0432\u0435\u0442\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0434\u0435\u0440\u0435\u0432\u044c\u044f \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 Accessibility Tree \u2014 AXTree);\n- \u0421\u0442\u0440\u043e\u0433\u043e\u0439 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0445 \u043f\u043e\u0434\u0446\u0435\u043b\u0435\u0439 (subgoals);\n- \u0412\u044b\u0441\u043e\u043a\u043e\u0439 \u0446\u0435\u043d\u043e\u0439 \u043d\u0435\u043e\u0431\u0440\u0430\u0442\u0438\u043c\u044b\u0445 \u043e\u0448\u0438\u0431\u043e\u043a (\u043e\u0448\u0438\u0431\u043e\u0447\u043d\u043e\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u0435 \u0442\u0438\u043a\u0435\u0442\u0430, \u043d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u043c\u0443\u0442\u0430\u0446\u0438\u044f \u0434\u0430\u043d\u043d\u044b\u0445).\n\n### 1.2. \u0422\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 (Rationale)\n\u0426\u0435\u043f\u043e\u0447\u043a\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 (Chain-of-Thought / ReAct) \u043f\u0440\u0438\u043d\u0443\u0436\u0434\u0430\u0435\u0442 \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u0448\u0430\u0433\u0435 $t$ \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u043a\u0440\u044b\u0442\u043e\u0435 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435 $R_t = \\text{Thought}(\\dots)$ \u043f\u0435\u0440\u0435\u0434 \u043d\u0435\u043f\u043e\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u0432\u044b\u0431\u043e\u0440\u043e\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f $A_t = \\text{Action}(\\dots)$. \u041e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e CoT \u0440\u0435\u0448\u0430\u0435\u0442 \u0442\u0440\u0438 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u0432 \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u043c \u0432\u0435\u0431-\u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0435:\n1. **\u0421\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0438 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u043d\u044b\u0439 grounding:** \u0421\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0446\u0435\u043b\u0438 \u0437\u0430\u0434\u0430\u0447\u0438 \u0441 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u043c `bid` (BrowserGym browser identifier) \u0432 AXTree.\n2. **\u041e\u0442\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u043d\u0438\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f (Belief State Tracking):** \u041e\u0446\u0435\u043d\u043a\u0430 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u0433\u043e \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0438 \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u044f \u0434\u0438\u043d\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439 \u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 (\u043c\u043e\u0434\u0430\u043b\u044c\u043d\u044b\u0435 \u043e\u043a\u043d\u0430, \u0441\u043f\u0438\u043d\u043d\u0435\u0440\u044b \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438, \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0430\u043b\u0435\u0440\u0442\u044b).\n3. **\u041f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 \u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f:** \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u043f\u0435\u0440\u0435\u0434 \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0435\u0439 \u043d\u0435\u043e\u0431\u0440\u0430\u0442\u0438\u043c\u043e\u0433\u043e \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f.\n\n### 1.3. \u0424\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b\n- **\u041d\u0443\u043b\u0435\u0432\u0430\u044f \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 ($H_0$):** \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 CoT-\u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 \u043d\u0435 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0443\u0441\u043f\u0435\u0448\u043d\u043e\u0441\u0442\u044c \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0437\u0430\u0434\u0430\u0447 \u0430\u0433\u0435\u043d\u0442\u0430\u043c\u0438 \u0432 WorkArena++ \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u0441 \u043f\u0440\u044f\u043c\u043e\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0435\u0439 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439:\n  $$H_0: \\text{SR}_{\\text{CoT}} \\le \\text{SR}_{\\text{Direct}}$$\n- **\u0410\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 ($H_1$):** \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 CoT \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043f\u043e\u0432\u044b\u0448\u0430\u0435\u0442 \u0434\u043e\u043b\u044e \u0443\u0441\u043f\u0435\u0448\u043d\u043e \u0440\u0435\u0448\u0435\u043d\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447:\n  $$H_1: \\text{SR}_{\\text{CoT}} > \\text{SR}_{\\text{Direct}}$$\n- **\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 ($H_2$):** \u042d\u0444\u0444\u0435\u043a\u0442 \u043f\u0440\u0438\u0440\u043e\u0441\u0442\u0430 $\\Delta \\text{SR} = \\text{SR}_{\\text{CoT}} - \\text{SR}_{\\text{Direct}}$ \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043a\u043e\u0440\u0440\u0435\u043b\u0438\u0440\u0443\u0435\u0442 \u0441\u043e \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c\u044e \u0437\u0430\u0434\u0430\u0447\u0438 (\u0433\u043b\u0443\u0431\u0438\u043d\u043e\u0439 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438 \u0438 \u0447\u0438\u0441\u043b\u043e\u043c \u043f\u043e\u0434\u0446\u0435\u043b\u0435\u0439): \u043d\u0430 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u044b\u0445 \u043c\u043d\u043e\u0433\u043e\u044d\u0442\u0430\u043f\u043d\u044b\u0445 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044f\u0445 ServiceNow \u0432\u044b\u0438\u0433\u0440\u044b\u0448 \u043e\u0442 CoT \u0432\u044b\u0448\u0435, \u0447\u0435\u043c \u043d\u0430 \u0430\u0442\u043e\u043c\u0430\u0440\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447\u0430\u0445 \u043f\u043e\u0438\u0441\u043a\u0430/\u043d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u0438.\n\n---\n\n## 2. \u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u0433\u0440\u0443\u043f\u043f \u0438 \u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 \u043f\u043b\u0430\u043d\n\n\u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043f\u043e \u043f\u0430\u0440\u043d\u043e\u0439 \u043c\u0435\u0436\u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0439 \u0441\u0445\u0435\u043c\u0435 \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0444\u0430\u043a\u0442\u043e\u0440\u0430\u043c\u0438 ($2 \\times 2 \\times M$ \u0444\u0430\u043a\u0442\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d):\n\n### 2.1. \u041d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435\n1. **\u0424\u0430\u043a\u0442\u043e\u0440 \u043f\u0440\u043e\u043c\u043f\u0442\u0438\u043d\u0433\u0430 (Prompting Regime, \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0438\u0441\u0441\u043b\u0435\u0434\u0443\u0435\u043c\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440):**\n   - **Direct (No-CoT / Control):** \u0410\u0433\u0435\u043d\u0442 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442, \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u0438 \u0442\u0435\u043a\u0443\u0449\u0435\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435 (AXTree) \u0438 \u043e\u0431\u044f\u0437\u0430\u043d \u0441\u0440\u0430\u0437\u0443 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u043c\u043e\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0432 \u0441\u0442\u0440\u043e\u0433\u043e\u043c \u0444\u043e\u0440\u043c\u0430\u0442\u0435 `Action: <action_call>`.\n   - **CoT (ReAct / Treatment):** \u0410\u0433\u0435\u043d\u0442 \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442 \u0431\u043b\u043e\u043a \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0434 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c: `Thought: <reasoning>\\nAction: <action_call>`.\n2. **\u0424\u0430\u043a\u0442\u043e\u0440 in-context \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432 (Exemplar Control, \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440):**\n   - **Zero-shot:** \u041c\u043e\u0434\u0435\u043b\u044c \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u0431\u0435\u0437 \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u0439 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0439.\n   - **Few-shot ($k=2$):** \u041c\u043e\u0434\u0435\u043b\u0438 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438. \u0414\u043b\u044f \u0433\u0440\u0443\u043f\u043f\u044b Direct \u0438\u0437 \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0438 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u043e\u043b\u044f `Thought:`, \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0430\u0440\u044b `(Observation, Action)`. \u042d\u0442\u043e \u0441\u0442\u0440\u043e\u0433\u043e \u0438\u0437\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u044d\u0444\u0444\u0435\u043a\u0442 \u043d\u0430\u043b\u0438\u0447\u0438\u044f \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 \u043e\u0442 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u043e\u0437\u043d\u0430\u043a\u043e\u043c\u043b\u0435\u043d\u0438\u044f \u0441 \u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0441\u043e\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0438 \u0444\u043e\u0440\u043c\u0430\u0442\u043e\u043c \u0441\u0440\u0435\u0434\u044b.\n3. **\u0424\u0430\u043a\u0442\u043e\u0440 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b \u0431\u044d\u043a\u0431\u043e\u043d\u0430 ($M$):**\n   - *\u041f\u0440\u043e\u043f\u0440\u0438\u0435\u0442\u0430\u0440\u043d\u044b\u0435 SOTA:* GPT-4o, Claude 3.5 Sonnet.\n   - *\u041e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 SOTA:* Llama-3.1-70B-Instruct, Qwen2.5-72B-Instruct.\n\n### 2.2. \u041c\u0430\u0442\u0440\u0438\u0446\u0430 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u0433\u0440\u0443\u043f\u043f\n\n| \u041a\u043e\u0434 \u0433\u0440\u0443\u043f\u043f\u044b | \u0420\u0435\u0436\u0438\u043c \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 | In-Context Learning | \u0412\u0445\u043e\u0434\u043d\u0430\u044f \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0446\u0438\u044f | \u0420\u043e\u043b\u044c \u0432 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 |\n| :--- | :--- | :--- | :--- | :--- |\n| **G1 (Ctrl-Zero)** | Direct (No-CoT) | Zero-shot | AXTree (BrowserGym) | \u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c 1 |\n| **G2 (Exp-Zero)** | CoT / ReAct | Zero-shot | AXTree (BrowserGym) | \u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0442\u0435\u0441\u0442\u043e\u0432\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430 1 |\n| **G3 (Ctrl-Few)** | Direct (No-CoT) | Few-shot ($k=2$) | AXTree (BrowserGym) | \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u0439 |\n| **G4 (Exp-Few)** | CoT / ReAct | Few-shot ($k=2$) | AXTree (BrowserGym) | \u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0442\u0435\u0441\u0442\u043e\u0432\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430 2 |\n| *G5 (Ablation-V)* | CoT / ReAct | Zero-shot | AXTree + Screenshot (Multimodal) | \u0410\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 |\n\n---\n\n## 3. \u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432 \u0438 \u0438\u0437\u043e\u043b\u044f\u0446\u0438\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0439\n\n\u0427\u0442\u043e\u0431\u044b \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044e\u044e \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u044c (internal validity), \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432\u0441\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f:\n\n1. **\u041f\u0430\u0440\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d (Paired Evaluation Protocol):**\n   - \u041a\u0430\u0436\u0434\u0430\u044f \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0430\u044f \u0442\u0435\u0441\u0442\u043e\u0432\u0430\u044f \u0437\u0430\u0434\u0430\u0447\u0430 $i \\in \\{1, \\dots, N\\}$ \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0438\u0437 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0441\u0438\u0434\u0430 $S_i$.\n   - \u041f\u0435\u0440\u0435\u0434 \u043a\u0430\u0436\u0434\u044b\u043c \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u043c \u0438\u043d\u0441\u0442\u0430\u043d\u0441 ServiceNow \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043f\u043e\u043b\u043d\u044b\u0439 \u0441\u0431\u0440\u043e\u0441 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f (database rollback / reset snapshot) \u043a \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u043c\u0443 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u0441\u043d\u0438\u043c\u043a\u0443, \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u044f \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0445 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432 \u043e\u0442 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439.\n   - \u0412\u0441\u0435 \u0433\u0440\u0443\u043f\u043f\u044b (G1\u2013G4) \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u043e\u043c \u043f\u0443\u043b\u0435 \u0437\u0430\u0434\u0430\u0447 \u0441 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u043c\u0438 \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f\u043c\u0438.\n\n2. **\u0414\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f:**\n   - \u0422\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f: $T = 0.0$ (\u0436\u0430\u0434\u043d\u043e\u0435 \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435) \u0434\u043b\u044f \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u0441 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c API; \u0434\u043b\u044f \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u044d\u043d\u0434\u043f\u043e\u0438\u043d\u0442\u043e\u0432 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441\u0438\u0434 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 (`seed=42`).\n   - `top_p = 1.0`, \u0448\u0442\u0440\u0430\u0444\u044b \u0437\u0430 \u0447\u0430\u0441\u0442\u043e\u0442\u0443 \u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u044b \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u044b.\n\n3. **\u041b\u0438\u043c\u0438\u0442\u044b \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u0437\u0430\u0432\u0438\u0441\u0430\u043d\u0438\u0439:**\n   - \u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 \u0448\u0430\u0433\u043e\u0432 \u043d\u0430 \u044d\u043f\u0438\u0437\u043e\u0434: $H_{\\max} = 30$ \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439. \u041f\u043e \u0438\u0441\u0447\u0435\u0440\u043f\u0430\u043d\u0438\u0438 \u0448\u0430\u0433\u043e\u0432 \u0437\u0430\u0434\u0430\u0447\u0435 \u043f\u0440\u0438\u0441\u0432\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0441\u0442\u0430\u0442\u0443\u0441 Failure.\n   - \u0422\u0430\u0439\u043c\u0430\u0443\u0442 \u043d\u0430 \u0448\u0430\u0433 \u043c\u043e\u0434\u0435\u043b\u0438: 60 \u0441\u0435\u043a\u0443\u043d\u0434.\n   - \u041e\u0431\u0449\u0438\u0439 \u0442\u0430\u0439\u043c\u0430\u0443\u0442 \u044d\u043f\u0438\u0437\u043e\u0434\u0430 \u0432 ServiceNow: 600 \u0441\u0435\u043a\u0443\u043d\u0434.\n\n4. **\u041d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 (BrowserGym API):**\n   - \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043d\u0430\u0431\u043e\u0440 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 BrowserGym: `click(bid)`, `fill(bid, text)`, `select_option(bid, value)`, `hover(bid)`, `scroll(direction)`, `press_key(key)`, `stop(answer)`.\n   - \u0412 \u0441\u043b\u0443\u0447\u0430\u0435 \u043e\u0448\u0438\u0431\u043a\u0438 \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0432 Direct-\u0440\u0435\u0436\u0438\u043c\u0435 \u0432\u044b\u0434\u0430\u0435\u0442\u0441\u044f \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0444\u0438\u0434\u0431\u0435\u043a \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u043e\u0431 \u043e\u0448\u0438\u0431\u043a\u0435 \u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0441\u0430 (\u043a\u0430\u043a \u0438 \u0432 CoT), \u043f\u0440\u0435\u0434\u043e\u0442\u0432\u0440\u0430\u0449\u0430\u044f \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u0437\u0430 \u0441\u0447\u0435\u0442 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0439.\n\n---\n\n## 4. \u0421\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432 \u0438 \u0444\u043e\u0440\u043c\u0430\u0442\u0430 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f\n\n### 4.1. \u041a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0448\u0430\u0431\u043b\u043e\u043d \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f\n```text\n[Goal Instruction]\n<\u0422\u0435\u043a\u0441\u0442 \u0437\u0430\u0434\u0430\u0447\u0438 \u0438\u0437 WorkArena++, \u043d\u0430\u043f\u0440.: \"Create a new hardware incident for user John Doe with high urgency\">\n\n[Current AXTree]\n<\u0418\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b \u0441 bid, \u043e\u0442\u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0447\u0435\u0440\u0435\u0437 BrowserGym parser>\n\n[Interaction History]\nStep 1: Action: ... | Feedback: ...\n...\nStep t-1: Action: ... | Feedback: ...\n```\n\n### 4.2. \u0421\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0432\u044b\u0445\u043e\u0434\u043e\u0432\n- **Direct Prompting (G1, G3):**\n  ```text\n  You are an enterprise web agent. Based on the observation and goal, output ONLY the next action.\n  Do not include any intermediate reasoning or explanation.\n  Format:\n  Action: <browsergym_action>\n  ```\n- **CoT / ReAct Prompting (G2, G4):**\n  ```text\n  You are an enterprise web agent. Analyze the current state, progress towards the goal, and identify the necessary target elements before acting.\n  Format:\n  Thought: <step-by-step reasoning about the observation, validation, and planning>\n  Action: <browsergym_action>\n  ```\n\n---\n\n## 5. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438 \u043f\u043b\u0430\u043d \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0434\u0430\u043d\u043d\u044b\u0445\n\n### 5.1. \u0417\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 (\u041c\u0435\u0442\u0440\u0438\u043a\u0438)\n1. **\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430:**\n   - **Success Rate ($\\text{SR}$):** \u0411\u0438\u043d\u0430\u0440\u043d\u0430\u044f \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f $Y_{i, g} \\in \\{0, 1\\}$, \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u0430\u044f \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u043c \u043e\u0440\u0430\u043a\u0443\u043b\u043e\u043c WorkArena++ (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0433\u043e \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0411\u0414 ServiceNow: \u0441\u043e\u0437\u0434\u0430\u043d \u043b\u0438 \u0442\u0438\u043a\u0435\u0442 \u0441 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u043c\u0438 \u043f\u043e\u043b\u044f\u043c\u0438, \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d \u043b\u0438 \u0432\u0435\u0440\u043d\u044b\u0439 \u0444\u0438\u043b\u044c\u0442\u0440 \u0438 \u0442.\u0434.).\n2. **\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438:**\n   - **Trajectory Length ($L$):** \u0427\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432 \u0434\u043e \u0432\u044b\u0437\u043e\u0432\u0430 `stop()` \u0438\u043b\u0438 \u0438\u0441\u0447\u0435\u0440\u043f\u0430\u043d\u0438\u044f \u0431\u044e\u0434\u0436\u0435\u0442\u0430.\n   - **Invalid Action Rate ($\\text{IAR}$):** \u0414\u043e\u043b\u044f \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0441 \u043e\u0448\u0438\u0431\u043a\u0430\u043c\u0438 \u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0441\u0430 \u0438\u043b\u0438 \u043d\u0435\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u043c\u0438 `bid` (\u043e\u0448\u0438\u0431\u043a\u0438 grounding).\n   - **Subgoal Completion Rate ($\\text{SCR}$):** \u0414\u043e\u043b\u044f \u0443\u0441\u043f\u0435\u0448\u043d\u043e \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u043d\u044b\u0445 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0445 \u0447\u0435\u043a\u043f\u043e\u0438\u043d\u0442\u043e\u0432 \u0432 \u043c\u043d\u043e\u0433\u043e\u044d\u0442\u0430\u043f\u043d\u044b\u0445 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044f\u0445 (\u043e\u0446\u0435\u043d\u043a\u0430 \u0447\u0435\u0440\u0435\u0437 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0435 \u0445\u0443\u043a\u0438 WorkArena++).\n3. **\u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438:**\n   - **Cost & Token Overhead:** \u0421\u0440\u0435\u0434\u043d\u0435\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u043d\u0430 \u044d\u043f\u0438\u0437\u043e\u0434 ($T_{\\text{out}}$) \u0438 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u043e\u0442\u0432\u0435\u0442\u0430 ($t_{\\text{latency}}$).\n\n### 5.2. \u041f\u043b\u0430\u043d \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\n\u041f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u043a\u0430\u0436\u0434\u044b\u0439 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 \u043f\u0440\u043e\u0433\u043e\u043d\u044f\u0435\u0442\u0441\u044f \u0432 \u043f\u0430\u0440\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 (\u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u0438 \u0442\u043e\u043c \u0436\u0435 \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u043e\u043c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0438), \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u043c\u0438:\n\n1. **\u041f\u0430\u0440\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u041c\u0430\u043a-\u041d\u0435\u043c\u0430\u0440\u0430 (McNemar's Test with Continuity Correction):**\n   - \u0421\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043c\u0430\u0442\u0440\u0438\u0446\u0430 \u0441\u043e\u043f\u0440\u044f\u0436\u0435\u043d\u043d\u043e\u0441\u0442\u0438 $2 \\times 2$ \u0438\u0441\u0445\u043e\u0434\u043e\u0432 \u0434\u043b\u044f \u043f\u0430\u0440 (Direct vs. CoT):\n     - $a$: Direct = \u0423\u0441\u043f\u0435\u0445, CoT = \u0423\u0441\u043f\u0435\u0445\n     - $b$: Direct = \u0423\u0441\u043f\u0435\u0445, CoT = \u041d\u0435\u0443\u0434\u0430\u0447\u0430\n     - $c$: Direct = \u041d\u0435\u0443\u0434\u0430\u0447\u0430, CoT = \u0423\u0441\u043f\u0435\u0445\n     - $d$: Direct = \u041d\u0435\u0443\u0434\u0430\u0447\u0430, CoT = \u041d\u0435\u0443\u0434\u0430\u0447\u0430\n   - \u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f:\n     $$\\chi^2 = \\frac{(|b - c| - 1)^2}{b + c}, \\quad df = 1$$\n   - \u041f\u0440\u0438 $b + c < 25$ \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u0447\u043d\u044b\u0439 \u0431\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 (Exact Binomial Test).\n   - \u0423\u0440\u043e\u0432\u0435\u043d\u044c \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u0438: $\\alpha = 0.05$.\n\n2. **\u0411\u0443\u0442\u0441\u0442\u0440\u0435\u043f-\u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b (Bootstrap CIs):**\n   - \u0420\u0430\u0441\u0447\u0435\u0442 95% \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c\u043d\u043e\u0433\u043e \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0430 \u0434\u043b\u044f \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438 \u0434\u043e\u043b\u0435\u0439 $\\Delta \\text{SR} = \\text{SR}_{\\text{CoT}} - \\text{SR}_{\\text{Direct}}$ \u043d\u0430 $B = 10\\,000$ \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0439.\n\n3. **\u0421\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f (GLMM):**\n   - \u0414\u043b\u044f \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u043e\u0433\u043e \u0443\u0447\u0435\u0442\u0430 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432 \u0438 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0445 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432 \u0437\u0430\u0434\u0430\u0447:\n     $$\\text{logit}(P(Y_{ij} = 1)) = \\beta_0 + \\beta_1 \\cdot \\text{Prompt} + \\beta_2 \\cdot \\text{FewShot} + \\beta_3 \\cdot \\text{Category} + u_j + \\varepsilon_{ij}$$\n     \u0433\u0434\u0435 $u_j \\sim \\mathcal{N}(0, \\sigma_u^2)$ \u2014 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442 (random effect) \u0434\u043b\u044f \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0438 $j$. \u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u043b\u0438\u044f\u043d\u0438\u0435 CoT ($\\beta_1$) \u043e\u0442 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0438 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447 ServiceNow.\n\n4. **\u0422\u0430\u043a\u0441\u043e\u043d\u043e\u043c\u0438\u044f \u043e\u0448\u0438\u0431\u043e\u043a (Error Attribution Analysis):**\n   \u0412\u0441\u0435 \u043d\u0435\u0443\u0434\u0430\u0447\u043d\u044b\u0435 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043d\u0430 4 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438:\n   - *Planning Error:* \u0414\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b \u0441 \u0442\u043e\u0447\u043a\u0438 \u0437\u0440\u0435\u043d\u0438\u044f DOM, \u043d\u043e \u043b\u043e\u0433\u0438\u043a\u0430 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0430 (\u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d \u0448\u0430\u0433, \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a).\n   - *Grounding Error:* \u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043e\u0431\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u043a \u043d\u0435\u0432\u0435\u0440\u043d\u043e\u043c\u0443 `bid` \u0438\u043b\u0438 \u043d\u0435 \u0440\u0435\u043b\u0435\u0432\u0430\u043d\u0442\u043d\u043e\u043c\u0443 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0443.\n   - *Syntax Error:* \u0421\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u043d\u0435\u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430.\n   - *Horizon Timeout:* \u0418\u0441\u0447\u0435\u0440\u043f\u0430\u043d \u043b\u0438\u043c\u0438\u0442 \u0432 30 \u0448\u0430\u0433\u043e\u0432 \u043f\u0440\u0438 \u0431\u0435\u0441\u043a\u043e\u043d\u0435\u0447\u043d\u043e\u043c \u0437\u0430\u0446\u0438\u043a\u043b\u0438\u0432\u0430\u043d\u0438\u0438 (looping).\n\n---\n\n## 6. \u041e\u0446\u0435\u043d\u043a\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u0438 \u0438 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 (Feasibility)\n\n1. **\u0420\u0430\u0437\u043c\u0435\u0440 \u0432\u044b\u0431\u043e\u0440\u043a\u0438:**\n   - \u0421\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0441\u043f\u043b\u0438\u0442 WorkArena++ \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 $\\sim 250$ \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432 \u0437\u0430\u0434\u0430\u0447 (\u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438: Service Catalog, Knowledge Management, List/Filter, Form Filling).\n   - \u041f\u0440\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f $1 - \\beta = 0.80$ \u0438 $\\alpha = 0.05$, \u0432\u044b\u0431\u043e\u0440\u043a\u0430 \u0432 $N = 250$ \u043f\u0430\u0440\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447 \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u0430 \u043d\u0430\u0434\u0435\u0436\u043d\u043e \u0434\u0435\u0442\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 $\\Delta \\text{SR} \\ge 6.5\\%$.\n\n2. **\u041e\u0446\u0435\u043d\u043a\u0430 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0431\u044e\u0434\u0436\u0435\u0442\u0430:**\n   - 4 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0433\u0440\u0443\u043f\u043f\u044b $\\times 250$ \u0437\u0430\u0434\u0430\u0447 $= 1\\,000$ \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0439 \u043d\u0430 \u043e\u0434\u043d\u0443 \u043c\u043e\u0434\u0435\u043b\u044c.\n   - \u041f\u0440\u0438 \u0441\u0440\u0435\u0434\u043d\u0435\u0439 \u0434\u043b\u0438\u043d\u0435 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438 $L \\approx 10$ \u0448\u0430\u0433\u043e\u0432:\n     - Direct: $\\approx 10$ \u0448\u0430\u0433\u043e\u0432 $\\times 150$ \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432\u044b\u0432\u043e\u0434\u0430 $= 1\\,500$ \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432\u044b\u0432\u043e\u0434\u0430 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443.\n     - CoT: $\\approx 10$ \u0448\u0430\u0433\u043e\u0432 $\\times 600$ \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432\u044b\u0432\u043e\u0434\u0430 $= 6\\,000$ \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432\u044b\u0432\u043e\u0434\u0430 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443.\n     - \u0412\u0445\u043e\u0434\u043d\u043e\u0439 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 (AXTree): $\\approx 3\\,500$ \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u043d\u0430 \u0448\u0430\u0433 $\\times 10$ \u0448\u0430\u0433\u043e\u0432 $= 35\\,000$ \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432\u0432\u043e\u0434\u0430 \u043d\u0430 \u044d\u043f\u0438\u0437\u043e\u0434.\n   - \u0421\u0443\u043c\u043c\u0430\u0440\u043d\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u043d\u0430 2 \u0444\u043b\u0430\u0433\u043c\u0430\u043d\u0441\u043a\u0438\u0445 \u043c\u043e\u0434\u0435\u043b\u044f\u0445 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0443\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0438\u043f\u0438\u0447\u043d\u044b\u0439 \u0430\u043a\u0430\u0434\u0435\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0433\u0440\u0430\u043d\u0442\u043e\u0432\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 \u043d\u0430 API.\n\n3. **\u0421\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0440\u0438\u0441\u043a\u043e\u0432 \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u0438 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b:**\n   - \u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043c\u043e\u043d\u0438\u0442\u043e\u0440\u0438\u043d\u0433 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u0430 ServiceNow \u0438 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u043f\u0438\u043d\u0433\u0430 \u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u043c \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u044d\u043f\u0438\u0437\u043e\u0434\u0430;\n   - \u041f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u043a \u044d\u043f\u0438\u0437\u043e\u0434\u0430 \u043f\u0440\u0438 \u0432\u043e\u0437\u043d\u0438\u043a\u043d\u043e\u0432\u0435\u043d\u0438\u0438 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0439 \u0441\u0435\u0442\u0435\u0432\u043e\u0439 \u043e\u0448\u0438\u0431\u043a\u0438 (502/504) \u0441 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u043c \u043b\u043e\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u043c, \u0447\u0442\u043e\u0431\u044b \u0441\u0435\u0442\u0435\u0432\u044b\u0435 \u0441\u0431\u043e\u0438 \u043d\u0435 \u0442\u0440\u0430\u043a\u0442\u043e\u0432\u0430\u043b\u0438\u0441\u044c \u043a\u0430\u043a \u043e\u0448\u0438\u0431\u043a\u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0430\u0433\u0435\u043d\u0442\u0430.\n\n---\n\n## 7. \u0417\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435\n\n\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u0438\u0437\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u0444\u0430\u043a\u0442\u043e\u0440 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044f (Chain-of-Thought) \u043e\u0442 \u0441\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432 (\u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432, \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0439 \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438, \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f) \u0438 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0441\u0442\u0440\u043e\u0433\u0438\u0439 \u0430\u043f\u043f\u0430\u0440\u0430\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0433\u0438\u043f\u043e\u0442\u0435\u0437 \u043d\u0430 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0435 WorkArena++. \u041f\u043b\u0430\u043d \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0433\u043e\u0442\u043e\u0432 \u043a \u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u0432 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u043d\u043e\u043c \u0444\u0440\u0435\u0439\u043c\u0432\u043e\u0440\u043a\u0435 BrowserGym.", "summary": "\u0421\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u043f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 CoT \u0432 WorkArena++: \u0444\u0430\u043a\u0442\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u043b\u0430\u043d, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432, \u0441\u0442\u0430\u0442-\u0430\u043d\u0430\u043b\u0438\u0437 \u0438 \u043e\u0446\u0435\u043d\u043a\u0430 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432.", "assumptions": ["\u0411\u0435\u043d\u0447\u043c\u0430\u0440\u043a WorkArena++ \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u043d\u043e\u0433\u043e \u043e\u0442\u043a\u0430\u0442\u0430 (reset snapshot) \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u044b ServiceNow \u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u043c \u043a\u0430\u0436\u0434\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0438.", "\u0422\u0435\u043a\u0441\u0442\u043e\u0432\u043e\u0435 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 Accessibility Tree (AXTree) \u0447\u0435\u0440\u0435\u0437 BrowserGym \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440\u044b \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 (bid) \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u044b\u043c\u0438 \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u043e\u0434\u043d\u043e\u0433\u043e \u0441\u043d\u0438\u043c\u043a\u0430 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f.", "\u041e\u0440\u0430\u043a\u0443\u043b WorkArena++ \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u